    val.resetDeser();

    const U32 idBase = this->getIdBase();
    FW_ASSERT(id >= idBase, id, idBase);

    switch (id - idBase) {

  #for $ids, $tlm_name, $type, $size, $update, $comment, $typeinfo in $channels:
