			if (mutestatus == 0) {
				mutestatus = 1;
				jQuery("#volimage").attr("src","/images/volume_mute.png");
			} else  {
				mutestatus = 0;
				jQuery("#volimage").attr("src","/images/volume.png");
			}
			jQuery.ajax("/web/vol?set=mute")
		});

		getStatusInfo();
	});
	</script>
