  void ${class_name}::loadParameters(void) {

    Fw::ParamBuffer buff;
    Fw::SerializeStatus stat = Fw::FW_SERIALIZE_OK;
    FW_ASSERT(this->m_${ParamGet_Name}_OutputPort[0].isConnected());

    FwPrmIdType _id; 
  #for $ids, $prmname, $type, $osets, $osaves, $size, $default, $comment, $typeinfo in $parameters:
    // choose parameter ID to get
    #if len($ids) == 1
    _id = this->getIdBase() + PARAMID_${prmname.upper};
    #else
       switch (this->getInstance()) {
       #set $inst = 0
       #for $id in $ids
          case ${inst}:
             _id = this->getIdBase() + PARAMID_${prmname.upper}_${inst};
             break;
          #set $inst = $inst + 1
       #end for
          default:
             // Silence compiler warning
             _id = (FwPrmIdType) 0;
             FW_ASSERT(0,this->getInstance());
             break;
       }
    #end if   
    // Get parameter ${prmname}
    this->m_param_${prmname}_valid =
      this->m_${ParamGet_Name}_OutputPort[0].invoke(
          _id,
          buff
      );

    // Deserialize value
    this->m_paramLock.lock();

    if (this->m_param_${prmname}_valid == Fw::PARAM_VALID) {
    #if $typeinfo == "enum":
      FwEnumStoreType ${prmname}Val;
      stat = buff.deserialize(${prmname}Val);
      this->m_${prmname} = static_cast<$type>(${prmname}Val);
    #else
      stat = buff.deserialize(this->m_${prmname});
    #end if
      // If there was a deserialization issue, mark it invalid.
      if (stat != Fw::FW_SERIALIZE_OK) {
    #if $default == None:
        this->m_param_${prmname}_valid = Fw::PARAM_INVALID;
    #else if $type == "string":
        this->m_param_${prmname}_valid = Fw::PARAM_DEFAULT;
        // set default value
        this->m_${prmname} = "${default}";
    #else
        this->m_param_${prmname}_valid = Fw::PARAM_DEFAULT;
        // set default value
        this->m_${prmname} = ${default};
    #end if
      }
    }
    else {
    #if $default == None:
      // No default
    #else if $type == "string":
      // set default value
      this->m_param_${prmname}_valid = Fw::PARAM_DEFAULT;
      this->m_${prmname} = "${default}";
    #else
      // set default value
      this->m_param_${prmname}_valid = Fw::PARAM_DEFAULT;
      this->m_${prmname} = ${default};
    #end if
    }

    this->m_paramLock.unLock();

  #end for
    // Call notifier
    this->parametersLoaded();
  }

#end if
