        this->copyBuff(other.m_buf,this->getCapacity());
        return *this;
    }

    void ${argname}String::terminate(NATIVE_UINT_TYPE size) {
        // null terminate the string
        this->m_buf[size < sizeof(this->m_buf)?size:sizeof(this->m_buf)-1] = 0;
    }

