    \title{;position.title}
    \location{;position.location}
    \dates{;position.dates}
    \begin{position}
        \vspace{-.3cm}
        !if ;position.description
            \begin{itemize}
            !for ;point in ;position.description
                \item ;point
            !end for
            \end{itemize}
        !else
            \vspace{-.2cm}
        !end if
    \end{position}
!end for


\section{Other Projects}
\begin{itemize}
!for ;item in ;projects
    \item ;item
!end for
\end{itemize}


\section {University Activities}

\begin{format}
  \title{l}\location{r}\\
  \body\\
\end{format}

!for ;activity in ;university
    \title{\textbf{;activity.who}}
    \location{;activity.when}
    \begin{position}
        !if ;activity.what
            ;activity.what
        !else
            \vspace{-0.5cm}
        !end if
    \end{position}
!end for


\section {High School Activities}

!for ;activity in ;highSchool
    \title{\textbf{;activity.who}}
    \location{;activity.when}
    \begin{position}
        !if ;activity.what
            ;activity.what
        !else
            \vspace{-0.5cm}
        !end if
    \end{position}
!end for


\section{Education}

\begin{format}
  \title{l}\\
  \location{l}\dates{r}\\
  \body\\
\end{format}

!for ;school in ;education
    \title{\textbf{;school.degree}}
    \dates{;school.dates}
    \location{;school.school}
    \begin{position}
        \vspace{-.3cm}
        !if ;school.description
            \begin{itemize}
            !for ;point in ;school.description
                \item ;point
            !end for
            \end{itemize}
        !else
            \vspace{-.2cm}
        !end if
    \end{position}
!end for


\section{Awards}
\begin{itemize}
    !for ;award in ;awards
        \item ;award
    !end for
\end{itemize}


\section{Interests}
;interests


\vfill

\end{resume}
\end{sloppypar}
\end{document}

