  // ----------------------------------------------------------------------
  // Calls for messages received on command input ports
  // ----------------------------------------------------------------------

  void ${class_name} ::
    m_p_${Cmd_Name}_in(
        Fw::PassiveComponentBase* callComp,
        NATIVE_INT_TYPE portNum,
        FwOpcodeType opCode,
        U32 cmdSeq,
        Fw::CmdArgBuffer &args
    )
  {

    // Select base class function based on opcode
    FW_ASSERT(callComp);
    ${class_name}* compPtr =
      (${class_name}*) callComp;

    const U32 idBase = callComp->getIdBase();
    FW_ASSERT(opCode >= idBase, opCode, idBase);
    switch (opCode - idBase) {

  #for $mnemonic, $opcodes, $sync, $priority, $full, $comment in $commands:
    #if len($opcodes) == 1
      case OPCODE_${mnemonic.upper}: /*!< $comment */
    #else
      #set $inst = 0
      #for $opcode in $opcodes:
      case OPCODE_${mnemonic.upper}_${inst}: /*!< $comment */
         #set $inst = $inst + 1
      #end for
    #end if
        compPtr->${mnemonic}_cmdHandlerBase(
            opCode,
            cmdSeq,
            args
        );
        break;

  #end for
  #for $ids, $prmname, $type, $osets, $osaves, $size, $default, $comment, $typeinfo in $parameters:
    #if len($ids) == 1
      case OPCODE_${prmname.upper}_SET:
    #else
      #set $inst = 0
      #for $id in $ids
      case OPCODE_${prmname.upper}_${inst}_SET:
        #set $inst = $inst + 1
      #end for
    #end if
      {
        Fw::CommandResponse _cstat = compPtr->paramSet_${prmname}(args);
        compPtr->cmdResponse_out(
            opCode,
            cmdSeq,
            _cstat
        );
        break;
      }
    #if len($ids) == 1
      case OPCODE_${prmname.upper}_SAVE:
    #else
      #set $inst = 0
      #for $id in $ids
      case OPCODE_${prmname.upper}_${inst}_SAVE:
        #set $inst = $inst + 1
      #end for
    #end if
      {
        Fw::CommandResponse _cstat = compPtr->paramSave_${prmname}();
        compPtr->cmdResponse_out(
            opCode,
            cmdSeq,
            _cstat
        );
        break;
      }
  #end for
      default: {
        compPtr->cmdResponse_out(
            opCode,cmdSeq,
            Fw::COMMAND_INVALID_OPCODE
        );
        break;
      }

    }

  }

  void ${class_name} ::
    cmdResponse_out(
        FwOpcodeType opCode,
        U32 cmdSeq,
        Fw::CommandResponse response
    )
  {
    FW_ASSERT(this->m_${CmdStatus_Name}_OutputPort[0].isConnected());
    this->m_${CmdStatus_Name}_OutputPort[0].invoke(opCode,cmdSeq,response);
  }

#end if
#if $has_commands
  // ----------------------------------------------------------------------
  // Base class command functions
  // ----------------------------------------------------------------------

  #for $mnemonic, $opcodes, $sync, $priority, $full, $comment in $commands:
  void ${class_name} ::
    ${mnemonic}_cmdHandlerBase(
        FwOpcodeType opCode,
        U32 cmdSeq,
        Fw::CmdArgBuffer &args
    )
  {

    #if $sync == 'guarded' or $sync == 'sync':
      #set $args = $command_args[$mnemonic]
      #if len($args):
    // Deserialize the arguments
    Fw::SerializeStatus _status = Fw::FW_SERIALIZE_OK;

    // Reset the buffer
    args.resetDeser();

        #for $arg_name, $arg_type, $comment, $is_enum in $args:
    $arg_type $arg_name;
          #if $is_enum == "enum":
    FwEnumStoreType ${arg_name}Int;
    _status = args.deserialize(${arg_name}Int);
    $arg_name = (${arg_type})${arg_name}Int;
          #else
    _status = args.deserialize($arg_name);
          #end if
    if (_status != Fw::FW_SERIALIZE_OK) {
      if (this->m_${CmdStatus_Name}_OutputPort[0].isConnected()) {
        this->m_${CmdStatus_Name}_OutputPort[0].invoke(
            opCode,
            cmdSeq,Fw::COMMAND_FORMAT_ERROR
        );
      }
      return;
    }

        #end for
      #end if
\#if FW_CMD_CHECK_RESIDUAL
    // Make sure there was no data left over.
    // That means the argument buffer size was incorrect.
    if (args.getBuffLeft() != 0) {
      if (this->m_${CmdStatus_Name}_OutputPort[0].isConnected()) {
        this->m_${CmdStatus_Name}_OutputPort[0].invoke(
            opCode,
            cmdSeq,Fw::COMMAND_FORMAT_ERROR
        );
      }
      return;
    }
\#endif
      #if $sync == 'guarded'
    this->lock();
      #end if
      #if len($args) == 0:
    this->${mnemonic}_cmdHandler(opCode,cmdSeq);
      #else
    this->${mnemonic}_cmdHandler(
        opCode,
        cmdSeq,
        $command_args_str($args)
    );
      #end if
      #if $sync == 'guarded'
    this->unLock();
      #end if

    #end if
    #if $sync == 'async'
    // Call pre-message hook
    this->${mnemonic}_preMsgHook(opCode,cmdSeq);

    // Defer deserializing arguments to the message dispatcher
    // to avoid deserializing and reserializing just for IPC
    ComponentIpcSerializableBuffer msg;
    Fw::SerializeStatus _status = Fw::FW_SERIALIZE_OK;

    // Serialize for IPC
    #if len($opcodes) == 1
    _status = msg.serialize((NATIVE_INT_TYPE)CMD_${mnemonic.upper()});
    #else
    switch (this->getInstance()) {
       #set $inst = 0
       #for $opcode in $opcodes
        case $inst:
            _status = msg.serialize((NATIVE_INT_TYPE)CMD_${mnemonic.upper()}_${inst});
            break;
         #set $inst = $inst + 1
       #end for
        default:
           // Silence compiler warning
           _status = (Fw::SerializeStatus) 0;
           FW_ASSERT(0,this->getInstance());
           break;
    };
    #end if
    FW_ASSERT (
        _status == Fw::FW_SERIALIZE_OK,
        static_cast<AssertArg>(_status)
        );

    // Fake port number to make message dequeue work
    NATIVE_INT_TYPE port = 0;
    _status = msg.serialize(port);
    FW_ASSERT (
        _status == Fw::FW_SERIALIZE_OK,
        static_cast<AssertArg>(_status)
    );

    _status = msg.serialize(opCode);
    FW_ASSERT (
        _status == Fw::FW_SERIALIZE_OK,
        static_cast<AssertArg>(_status)
    );

    _status = msg.serialize(cmdSeq);
    FW_ASSERT (
        _status == Fw::FW_SERIALIZE_OK,
        static_cast<AssertArg>(_status)
    );

    _status = msg.serialize(args);
    FW_ASSERT (
        _status == Fw::FW_SERIALIZE_OK,
        static_cast<AssertArg>(_status)
    );

    // send message
    Os::Queue::QueueBlocking _block =
      #if $full == 'block'
      Os::Queue::QUEUE_BLOCKING;
      #else
      Os::Queue::QUEUE_NONBLOCKING;
      #end if
    Os::Queue::QueueStatus qStatus =
      this->m_queue.send(msg, ${priority},_block);
      #if $full == 'drop'
    if (qStatus == Os::Queue::QUEUE_FULL) {
        this->incNumMsgDropped();
        return;
    }
      #end if
    FW_ASSERT(
        qStatus == Os::Queue::QUEUE_OK,
        static_cast<AssertArg>(qStatus)
    );

    #end if
  }

    #if $sync == "async":
  void ${class_name}::
    ${mnemonic}_preMsgHook(
        FwOpcodeType opCode,
        U32 cmdSeq
    )
  {
    // Defaults to no-op; can be overridden
  }

    #end if
