\#if FW_PORT_SERIALIZATION            
    } else if (this->m_serPort) {
 #if len($args) > 0:
        Fw::SerializeStatus status;
 #end if
        ${name}PortBuffer _buffer;
 #set $num = 0
 #for $arg in $args:
  #if $enum_marker[$num] == 'ENUM':
