  // ----------------------------------------------------------------------
  // Telemetry write functions
  // ----------------------------------------------------------------------

  #for $ids, $tlmname, $type, $size, $update, $comment, $typeinfo in $channels:
    #set $tlm_type = $type
    #if $type == "string":
      #set $tlm_type = "const Fw::TlmString&"
    #else if $typeinfo == "user"
      #set $tlm_type = "const " + $type + "&"
    #else
      #set $tlm_type = $type
