#if $abi.isa_name == 'aarch64' and $unit_cnt == 1
#if $public_only
#set atomic_use_asm = 'defined(__aarch64__) && defined(__ARM_FEATURE_ATOMICS)'
#else
#set atomic_use_asm = 'defined(ARCH_ARM) && defined(ARCH_ARM_FEAT_LSE)'
#end if
## For a single-unit structure, we can do atomic updates better than the
## compiler, by generating an atomic LD* instruction instead of an LDR/CAS
## sequence. It is not possible to do that in plain C without illegally casting
## the _Atomic away and back again.

#def atomic_fetch_op_bitmap(type_name, unit_type, unit_size, op)
#if $unit_size == 64
#set s, w = '', ''
#elif $unit_size == 32
#set s, w = '', 'w'
#elif $unit_size == 16
#set s, w = 'h', 'w'
#elif $unit_size == 8
#set s, w = 'b', 'w'
#else
#raise ValueError("Invalid unit_size")
#end if
        ${unit_type} ret_u;
        switch(order) {
        case memory_order_relaxed:
                // ${unit_size}-bit atomic load and ${op}, relaxed order
                __asm__ volatile ("ld${op}${s} %${w}2, %${w}0, %1"
                        : "=r"(ret_u), "+Q"(*b1) : "r"(b2.bf[0]));
                break;
        case memory_order_acquire:
        case memory_order_consume:
                // ${unit_size}-bit atomic load and ${op}, acquire order
                __asm__ volatile ("ld${op}a${s} %${w}2, %${w}0, %1"
                        : "=r"(ret_u), "+Q"(*b1) : "r"(b2.bf[0]));
                // Compiler acquire fence to prevent later stores migrating
                // before the above atomic load
                atomic_signal_fence(memory_order_acquire);
                break;
        case memory_order_release:
                // Compiler release fence to prevent earlier accesses migrating
                // after the below atomic load
                atomic_signal_fence(memory_order_release);
                // ${unit_size}-bit atomic load and ${op}, release order
                __asm__ volatile ("ld${op}l${s} %${w}2, %${w}0, %1"
                        : "=r"(ret_u), "+Q"(*b1) : "r"(b2.bf[0]));
                break;
        case memory_order_acq_rel:
        case memory_order_seq_cst:
        default:
                // ${unit_size}-bit atomic load and ${op}, acquire and release
                // order, with a full compiler barrier
                __asm__ volatile ("ld${op}al${s} %${w}2, %${w}0, %1"
                        : "=r"(ret_u), "+Q"(*b1) : "r"(b2.bf[0]) : "memory");
                break;
        }
        return ${type_name}_cast(ret_u);
#end def
#end if

${type_name}_t
${type_name}_atomic_union(_Atomic ${type_name}_t *b1, ${type_name}_t b2, memory_order order)
{
#if $abi.isa_name == 'aarch64' and $unit_cnt == 1
\#if $atomic_use_asm
${atomic_fetch_op_bitmap($type_name, $unit_type, $unit_size, 'set')}
\#else
#end if
       memory_order load_order =
               (order == memory_order_acq_rel) ? memory_order_acquire :
	       (order == memory_order_release) ? memory_order_relaxed :
	       order;

       ${type_name}_t old_value = atomic_load_explicit(b1, load_order);
       ${type_name}_t new_value;

       do {
               new_value = ${type_name}_union(old_value, b2);
       } while (!atomic_compare_exchange_weak_explicit(b1, &old_value,
               new_value, order, load_order));

       return old_value;
#if $abi.isa_name == 'aarch64' and $unit_cnt == 1
\#endif
#end if
}

${type_name}_t
${type_name}_atomic_intersection(_Atomic ${type_name}_t *b1, ${type_name}_t b2, memory_order order)
{
#if $abi.isa_name == 'aarch64' and $unit_cnt == 1
\#if $atomic_use_asm
       ${type_name}_t not_b2 = ${type_name}_inverse(b2);
       return ${type_name}_atomic_difference(b1, not_b2, order);
\#else
#end if
       memory_order load_order =
               (order == memory_order_acq_rel) ? memory_order_acquire :
	       (order == memory_order_release) ? memory_order_relaxed :
	       order;

       ${type_name}_t old_value = atomic_load_explicit(b1, load_order);
       ${type_name}_t new_value;

       do {
               new_value = ${type_name}_intersection(old_value, b2);
       } while (!atomic_compare_exchange_weak_explicit(b1, &old_value,
               new_value, order, load_order));

       return old_value;
#if $abi.isa_name == 'aarch64' and $unit_cnt == 1
\#endif
#end if
}

${type_name}_t
${type_name}_atomic_difference(_Atomic ${type_name}_t *b1, ${type_name}_t b2, memory_order order)
{
#if $abi.isa_name == 'aarch64' and $unit_cnt == 1
\#if $atomic_use_asm
${atomic_fetch_op_bitmap($type_name, $unit_type, $unit_size, 'clr')}
\#else
#end if
       ${type_name}_t not_b2 = ${type_name}_inverse(b2);
       return ${type_name}_atomic_intersection(b1, not_b2, order);
#if $abi.isa_name == 'aarch64' and $unit_cnt == 1
\#endif
#end if
}

